{% set cap_kwh = states('sensor.opti_battery_capacity_kwh') | float(0) %} {% set verbrauch_kw = states('input_number.opti_peak_verbrauch_kw') | float(0.8) %} {% set min_soc = states('input_number.minsoc') | float(10) %} {% set max_soc = states('input_number.maxsoc') | float(95) %} {% set aufschlag = states('input_number.opti_peak_min_aufschlag_ct') | float(10) %} {% set eta = 0.9 %} {# Integration adaptation: validate each list against the actual local calendar day (23/24/25h or 92/96/100 quarter-hours). Add fixed-duration slots to UTC midnight; this preserves both occurrences of a repeated hour without inventing a spring-forward hour. #}
{% set ns = namespace(prices=[], future=[], raster_ok=true) %} {% set heute = today_at('00:00') %} {% for key in ['today', 'tomorrow'] %}
  {% set arr = state_attr('sensor.opti_price_series', key) %}
  {% if arr is iterable and arr is not string and arr | length > 0 %}
    {% set laenge = arr | length %}
    {% set base = heute if key == 'today' else heute + timedelta(days=1) %} {% set day_hours = ((base + timedelta(days=1)).timestamp() - base.timestamp()) / 3600 %} {% if laenge not in [day_hours, day_hours * 4] %}
      {% set ns.raster_ok = false %}
    {% endif %}
    {% set slot_h = 1 if laenge == day_hours else 0.25 %}
    {% for it in arr %}
      {% if it is mapping %}{% set p = it.get('total', it.get('price', it.get('value'))) %}{% else %}{% set p = it %}{% endif %}
      {% set p = p | float(none) %}
      {% if p is not none %}
        {% set ns.prices = ns.prices + [p] %}
        {% set ns.future = ns.future + [[(base | as_utc) + timedelta(hours=loop.index0 * slot_h), p, slot_h]] %}
      {% endif %}
    {% endfor %}
  {% endif %}
{% endfor %} {% set n = ns.prices | length if ns.raster_ok else 0 %} {# 2. Wiederauflade-Horizont: bis naechster Sonnenaufgang plus Puffer
   (1 h bei binary_sensor.opti_pv_reichtag on, sonst 3 h), solange fuer
   den Tag dieses Sonnenaufgangs ein guter Score in Sicht ist; sonst
   36 h.
   Tagsueber + guter Heute-Score -> leer. #}
{% set s_heute = states('sensor.opti_forecast_score') | float(-1) %} {% set horizont_max = ((now() | as_utc) + timedelta(hours=36)) | as_local %} {% if is_state('sun.sun', 'above_horizon') and s_heute > 2 %}
  {# Auf die volle Stunde gekappt (== Fensterstart), damit das Fenster
     wirklich leer ist - now() liesse die laufende Stunde durchrutschen,
     sobald Minute > 0. #}
  {% set horizont_ende = now().replace(minute=0, second=0, microsecond=0) %}
{% else %}
  {% set rising = state_attr('sun.sun', 'next_rising') %}
  {% set rise = (rising | as_datetime | as_local) if rising else none %}
