     unknown und unavailable behalten konservativ die 36 h, ebenso ein
     fehlender Sonnenaufgang. #}
  {% if rise is not none and is_state('binary_sensor.opti_peak_horizont_lang', 'off') %}
    {# 1 h ist bewusst nicht 0 h: Bei Sonnenaufgang liefert auch ein
       freigegebener PV-Reichtag noch nichts. Am 27.07.2026 lag der
       Schnittpunkt von PV und Hausverbrauch erst ca. 06:30 bei
       Sonnenaufgang 05:45. #}
    {% set puffer = 1 if is_state('binary_sensor.opti_pv_reichtag','on') else 3 %}
    {% set horizont_ende = [rise + timedelta(hours=puffer), horizont_max] | min %}
