{% set start = now().replace(minute=0, second=0, microsecond=0) %} {% set fw = namespace(min=none) %} {% if n >= 4 %}
  {% for eintrag in ns.future %}
    {% set t = eintrag[0] %}
    {% set p = eintrag[1] %}
    {% if t >= start and t < horizont_ende %}
      {% set fw.min = p if fw.min is none else ([fw.min, p] | min) %}
    {% endif %}
  {% endfor %}
{% endif %} {% set fenster_min = fw.min %} {# 3b. Zweiter Durchlauf: Zukunftsslots im Horizont klassifizieren
   (Midrank-Perzentil, Grenzen unveraendert) UND zusaetzlich oekonomisch
   filtern (p >= fenster_min + aufschlag). Fenster ab der aktuellen
   vollen Stunde: die laufenden Peak-Slots zaehlen mit, damit das Gate
   waehrend der Spitze nicht abfaellt (laufende Stunde konservativ voll
   gerechnet - bei Viertelstundenraster zaehlen dadurch bis zu 3 bereits
   vergangene Slots der laufenden Stunde mit). min_preis_vor_peak_ct
   bezieht sich weiterhin auf die erste GEZAEHLTE (also gefilterte)
   Peak-Stunde. f.ve/f.exp summieren STUNDEN (slot_h je Slot), nicht
   Slot-Anzahlen, da today/tomorrow unterschiedliche slot_h haben
   koennen - deshalb Namespace-Summe statt Zaehler * Konstante. #}
{% set load_hours = state_attr('sensor.opti_peak_load_profile', 'hours') %}
{% set load_methods = state_attr('sensor.opti_peak_load_profile', 'methods') %}
{% set f = namespace(ve=0.0, exp=0.0, ve_energy=0.0, exp_energy=0.0, profile_hours=0.0, minpre=none, summe=0.0, anz=0, peak_gesehen=false, ve_summe=0.0, ve_anz=0) %} {% if n >= 4 %}
  {% for eintrag in ns.future %}
    {% set t = eintrag[0] %}
    {% set p = eintrag[1] %}
    {% set slot_h = eintrag[2] %}
    {% set load_key = ((t.timestamp() // 3600) * 3600) | int | string %}
    {% set load_w = load_hours.get(load_key) | float(none) if load_hours is mapping else none %}
    {% set slot_kw = load_w / 1000 if load_w is not none and 0 <= load_w <= 50000 else verbrauch_kw %}
    {% set load_method = load_methods.get(load_key, 'fixed_setting') if load_methods is mapping else 'fixed_setting' %}
    {% if t >= start and t < horizont_ende %}
      {% set kleiner = ns.prices | select('lt', p) | list | length %}
      {% set gleich  = ns.prices | select('eq', p) | list | length %}
      {% set pct = (kleiner + 0.5 * gleich) / n %}
      {% set ist_peak_preis = fenster_min is none or p >= fenster_min + aufschlag %}
      {% if pct >= 0.80 and ist_peak_preis %}
        {% set f.ve = f.ve + slot_h %}{% set f.ve_energy = f.ve_energy + slot_kw * slot_h %}{% if 'profile' in load_method %}{% set f.profile_hours = f.profile_hours + slot_h %}{% endif %}{% set f.summe = f.summe + p %}{% set f.anz = f.anz + 1 %}{% set f.peak_gesehen = true %}
        {% set f.ve_summe = f.ve_summe + p %}{% set f.ve_anz = f.ve_anz + 1 %}
      {% elif pct >= 0.60 and ist_peak_preis %}
        {% set f.exp = f.exp + slot_h %}{% set f.exp_energy = f.exp_energy + slot_kw * slot_h %}{% if 'profile' in load_method %}{% set f.profile_hours = f.profile_hours + slot_h %}{% endif %}{% set f.summe = f.summe + p %}{% set f.anz = f.anz + 1 %}{% set f.peak_gesehen = true %}
      {% elif not f.peak_gesehen %}
        {% set f.minpre = p if f.minpre is none else ([f.minpre, p] | min) %}
      {% endif %}
    {% endif %}
  {% endfor %}
{% endif %} {# 4. Reserve in kWh und SoC (mit Entladeverlusten), Kappung bei maxsoc.
   Stundenlast je Slot aus Profil oder Ersatzwert; Energie bereits
   separat fuer VE und EXP integriert (siehe 3b). #}
{% set ve_kwh = f.ve_energy / eta %} {% set ges_kwh = (f.ve_energy + f.exp_energy) / eta %} {% if cap_kwh > 0 %}
  {% set ve_soc = [min_soc + ve_kwh / cap_kwh * 100, max_soc] | min %}
  {% set ges_soc = [min_soc + ges_kwh / cap_kwh * 100, max_soc] | min %}
{% else %}
  {% set ve_soc = max_soc %}
  {% set ges_soc = max_soc %}
{% endif %} {{ {'gueltig': n >= 4,
    've_soc': ve_soc | round(1),
    'ges_soc': ges_soc | round(1),
    've_stunden': f.ve | round(2),
    'exp_stunden': f.exp | round(2),
    'benoetigt_kwh': ges_kwh | round(2),
    'profile_hours': f.profile_hours,
    'assumed_load_w': ((f.ve_energy + f.exp_energy) / (f.ve + f.exp) * 1000) | round(1) if f.ve + f.exp > 0 else verbrauch_kw * 1000,
    'min_preis_vor_peak_ct': (f.minpre | round(2)) if f.minpre is not none else none,
    'peak_preis_avg_ct': ((f.summe / f.anz) | round(2)) if f.anz > 0 else none,
    've_preis_avg_ct': ((f.ve_summe / f.ve_anz) | round(2)) if f.ve_anz > 0 else none,
    'fenster_min_ct': (fenster_min | round(2)) if fenster_min is not none else none,
    'horizont_ende': horizont_ende.isoformat(),
    'branch': 've=' ~ f.ve ~ ' exp=' ~ f.exp ~ ' n=' ~ n ~ ' ende=' ~ horizont_ende.strftime('%d.%m %H:%M')} }}

